actions.script:
const result = {sql: null, columnsList: [], recordsList: [], messages: [], confirmation: null, allowChanges: false}
const sqlText = ec.web.secureRequestParameters.sql
const changes = String(context.allowChanges) == 'true'
if (sqlText) {
    result.sql = String(sqlText)
    result.allowChanges = changes
    const call = (name, parameters) => {
        const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.' + name).parameters(parameters).call() || {}
        if (ec.message.hasError()) { result.messages.push(ec.message.errorsString); ec.message.clearErrors(); return null }
        return out
    }
    if (changes && !context.token) {
        const classified = call('classify#Sql', {db, sqlText: result.sql})
        const changing = classified ? (classified.statements || []).filter((statement) => statement.changes) : []
        if (classified && changing.length) result.confirmation = {token: classified.token, changeCount: classified.changeCount || changing.length,
            confirmDatabaseName: classified.confirmDatabaseName || '', implicitCommit: !!classified.implicitCommit,
            ownTransactionCount: changing.filter((statement) => statement.ownTransaction).length, statements: changing}
    }
    if (!result.confirmation && !(changes && !context.token && result.messages.length)) {
        // nothing to confirm (no statement changes data), or confirmed: run
        const confirmed = changes && !!context.token
        const out = call('run#Sql', {db, sqlText: result.sql, allowChanges: confirmed, token: confirmed ? context.token : null,
            confirmDatabaseName: confirmed ? (context.confirmDatabaseName || null) : null, limit: parseInt(context.limit || '500', 10)})
        for (const one of (out && out.results) || []) {
            if (one.error) result.messages.push(one.error)
            else if (one.skipped) result.messages.push(ec.resource.expand('Statement ${seq} not run.', '', {seq: one.seq}))
            else if (!one.givesRows) result.messages.push(ec.resource.expand('Query altered ${rowsAffected} rows.', '', {rowsAffected: one.rowsAffected || 0}))
            else {
                result.columnsList.push(one.columns || [])
                result.recordsList.push(one.records || [])
                const count = (one.records || []).length
                result.messages.push(one.limitReached ? ec.resource.expand('Only showing first ${limit} rows.', '', {limit: count})
                    : ec.resource.expand('Showing all ${count} results.', '', {count}))
            }
        }
        if (out && out.rolledBack) result.messages.push(ec.l10n.localize('The changes were rolled back.'))
        if (out && out.cancelled) result.messages.push(ec.l10n.localize('The run was cancelled.'))
        if (out && out.timedOut) result.messages.push(ec.l10n.localize('The run timed out.'))
    }
}
ec.web.sessionAttributes['SqlTui.result'] = JSON.stringify(result)

// what the run transition gave, once
let result = null
try { result = JSON.parse(ec.web.sessionAttributes['SqlTui.result'] || 'null') } catch (e) { result = null }
if (result) ec.web.sessionAttributes.remove('SqlTui.result')
outerColumnsList = (result && result.columnsList) || []
outerRecordsList = (result && result.recordsList) || []
messageList = (result && result.messages) || []
confirmation = (result && result.confirmation) || null
sql = (result && result.sql) || ''
allowChanges = result && result.allowChanges ? 'true' : null

render-mode.text:
${JSON.stringify((outerColumnsList || []).flatMap((columns, columnsIndex) => {
            const records = outerRecordsList[columnsIndex] || []
            return [{t: 'text', id: 'SqlResultTitle' + columnsIndex, style: 'h5', text: 'Result Set ' + (columnsIndex + 1)},
                {t: 'formList', id: 'SqlResult' + columnsIndex, name: 'SqlResult' + columnsIndex,
                    columns: columns.map((column) => ({title: String(column)})),
                    rows: records.map((record, recordIndex) => ({id: String(recordIndex),
                        cells: record.map((curField) => curField == null ? '' : String(ec.l10n.format(curField, '')))})),
                    paging: {index: 0, size: records.length, count: records.length}}]
        }))}
